//! `attend` clap-derive command surface.
//!
//! This module is the canonical source for the runtime `--help` text and
//! the markdown reference at `docs/cli/attend.md` (generated by
//! `bin/gen-docs.rs`). Doc comments here become help strings; edit them
//! in one place and both surfaces update on rebuild. `gen-docs` reads the
//! tree through the library's `cli_command()`.

use crate::describe;
use clap::{Args, Parser, Subcommand};

/// The closing line of a bare `attend` and of `attend --help` (ADR-413 item 4).
const AFTER_HELP: &str = "In a session with the attend mod, the attend_* tools send, reply, join and list peers. This CLI is for hosts without the mod and for scripts.";

#[derive(Parser)]
#[command(
    name = "attend",
    version = concat!(env!("CARGO_PKG_VERSION"), " (", env!("ATTEND_COMMIT"), ")"),
    about = "Active awareness for Claude Code sessions",
    long_about = None,
    after_help = AFTER_HELP,
    disable_help_subcommand = true,
)]
pub(crate) struct Cli {
    #[command(subcommand)]
    pub(crate) command: Option<Commands>,
}

/// The nine top-level commands (ADR-413 item 1), then the one-release
/// aliases of the flat verbs they replace.
#[derive(Subcommand)]
pub(crate) enum Commands {
    /// Start the sensor loop (use with Monitor for async delivery)
    Run {
        /// Replay backlog signals on startup before normal cadence
        #[arg(long)]
        catchup: bool,
    },

    #[command(about = describe::LISTEN)]
    Listen {
        #[command(subcommand)]
        sub: Option<ListenCmd>,

        /// Print the state as one JSON document
        #[arg(long, global = true)]
        json: bool,
    },

    /// Send, reply to, read, count and delete messages, and tombstone a session (default: inbox)
    #[command(args_conflicts_with_subcommands = true)]
    Message {
        #[command(flatten)]
        inbox: InboxFlags,

        #[command(subcommand)]
        sub: Option<MessageCmd>,
    },

    /// Join, leave, list and manage channels and scenes (default: list)
    Channel(ChannelGroup),

    /// List sessions, show this session's identity and the running loops (default: list)
    #[command(args_conflicts_with_subcommands = true)]
    Peer {
        #[command(flatten)]
        list: JsonArgs,

        #[command(subcommand)]
        sub: Option<PeerCmd>,
    },

    /// Keep the prompt cache warm across idle stretches (ADR-182; default: status)
    Keepwarm {
        #[command(subcommand)]
        sub: Option<KeepwarmCmd>,
    },

    /// Launch the interactive chat TUI (ADR-120)
    Chat {
        /// Arguments passed through to the `attend-chat` binary
        #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
        passthrough: Vec<String>,
    },

    /// List sensors and audit their permissions (default: list)
    Sensor {
        #[command(subcommand)]
        sub: Option<SensorCmd>,
    },

    /// Manage configuration (default: show)
    Config {
        #[command(subcommand)]
        sub: Option<ConfigCmd>,
    },

    // The one-release aliases of ADR-413 item 5: each old flat verb parses
    // what it parsed, prints the new form on stderr, then runs the new verb
    // with the same stdout and exit code. Issue #982 removes them in the
    // release after the one that ships the groups, and adds each name to
    // tests/legacy_removed.rs.
    #[command(hide = true)]
    Send(SendArgs),
    #[command(hide = true)]
    Reply(ReplyArgs),
    #[command(hide = true)]
    Inbox(InboxArgs),
    #[command(hide = true)]
    Unread(JsonArgs),
    #[command(hide = true)]
    Cleanup(CleanupArgs),
    #[command(hide = true)]
    Join(JoinArgs),
    #[command(hide = true)]
    Leave(LeaveArgs),
    #[command(hide = true)]
    Channels(ChannelGroup),
    #[command(hide = true)]
    Dissolve(NameArg),
    #[command(hide = true)]
    Scene(SceneArgs),
    #[command(hide = true)]
    Scenes,
    #[command(hide = true)]
    Peers(JsonArgs),
    #[command(hide = true)]
    Whoami(WhoamiArgs),
    #[command(hide = true)]
    Status(JsonArgs),
    #[command(hide = true)]
    Sensors,
    #[command(hide = true)]
    Permissions {
        #[command(subcommand)]
        sub: Option<PermissionsCmd>,
    },
    #[command(hide = true)]
    Tune(TuneArgs),
}

/// Subcommands for `attend message`. With no subcommand, defaults to `inbox`.
#[derive(Subcommand)]
pub(crate) enum MessageCmd {
    #[command(about = describe::SEND)]
    Send(SendArgs),

    #[command(about = describe::REPLY)]
    Reply(ReplyArgs),

    #[command(about = describe::INBOX)]
    Inbox(InboxArgs),

    #[command(about = describe::UNREAD)]
    Unread(JsonArgs),

    // `with_limits` writes this verb's help with the limits it applies.
    /// Reap signal files whose owning project is gone, and prune empty project dirs
    Cleanup(CleanupArgs),

    // `with_limits` writes this verb's long help with the limits it applies.
    /// Mark for deletion the messages no live session still has to read
    Delete(DeleteArgs),

    /// Tombstone a session that has exited, so every reader skips its messages
    ///
    /// The drain, the mod, `attend message unread`, the Monitor poller and
    /// `attend message inbox` all skip what a tombstoned session sent, and
    /// the drain records it read, up to when it was tombstoned; what the
    /// session sends later, back under --resume, shows. Only an agent's
    /// session that this host saw exit is tombstoned: a person's id, a
    /// session that may still read the bus, an id such a session had
    /// before /clear and this session's own are refused. Its messages stay
    /// on disk; `attend message delete --everywhere --from <id>` marks them
    /// for deletion (ADR-404 D3e).
    Tombstone(TombstoneArgs),
}

/// The help of the verbs that state a limit, written from the constants
/// that set it, so the text cannot drift from the behaviour.
pub(crate) fn with_limits(cmd: clap::Command) -> clap::Command {
    let grace = attend_presence::heartbeat::DEFAULT_GRACE.as_secs();
    let days = crate::cmd::cleanup::MARK_REAP_DAYS;
    let sessions = crate::cmd::cleanup::MARK_REAP_SESSIONS;
    let reap = format!(
        "{days} days after the mark, or for a message in a project tray once that project has started {sessions} \
         Claude Code sessions since, each /clear counting as one"
    );
    let delete = format!(
        "Mark for deletion the messages no live session still has to read\n\n\
         A message is marked when it is in the scope, older than --older-than, older than {grace} seconds, and \
         no session that may still read the bus would be delivered it: a session keeps what `attend message \
         unread` counts for it, its cold start included, and one this host cannot judge keeps its mail while \
         its last heartbeat is under {days} days old. A \
         person in attend-chat holds nothing. Every reader skips a marked message, and `attend message \
         cleanup` removes it {reap} (ADR-404 D3e). --undo takes a delete back, and its messages are delivered \
         again, while cleanup has not yet removed them."
    );
    let cleanup = format!(
        "Reap signal files whose owning project is gone, and prune empty project dirs. Lifetime is bound to \
         project liveness (ADR-136); the one removal by age is of a message `attend message delete` marked, \
         {reap} (ADR-404 D3e)."
    );
    // `mut_subcommands` edits each in place; `mut_subcommand` would move the
    // edited one to the end and reorder the help and the generated docs.
    cmd.mut_subcommands(|top| {
        if top.get_name() != "message" {
            return top;
        }
        top.mut_subcommands(|verb| match verb.get_name() {
            "delete" => verb.about(delete.lines().next().unwrap_or_default().to_string()).long_about(delete.clone()),
            "cleanup" => verb.about(cleanup.clone()),
            _ => verb,
        })
    })
}

/// Subcommands for `attend channel`. With no subcommand, defaults to `list`.
#[derive(Subcommand)]
pub(crate) enum ChannelCmd {
    #[command(about = describe::CHANNELS)]
    List(ChannelListArgs),

    #[command(about = describe::JOIN)]
    Join(JoinArgs),

    #[command(about = describe::LEAVE)]
    Leave(LeaveArgs),

    /// Create a channel without joining it (pinned so it persists empty)
    Create {
        /// Channel name (with or without the # prefix)
        name: String,
        /// Optional single-line description (all trailing words)
        #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
        description: Vec<String>,
    },

    /// Set or replace a channel's single-line description
    Describe {
        /// Channel name (with or without the # prefix)
        name: String,
        /// The description text (all trailing words; empty clears)
        #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
        description: Vec<String>,
    },

    /// Pin a channel so it persists when empty
    Pin(NameArg),

    /// Unpin a channel; it is removed if empty
    Unpin(NameArg),

    /// Dissolve a channel (removes it for every member)
    Dissolve(NameArg),

    /// Activate a named scene (reconfigure channel membership; `scene private` leaves all channels)
    Scene(SceneArgs),

    /// List available scenes
    Scenes,
}

