#[derive(Args)]
pub(crate) struct SendArgs {
    /// Send a direct message: to a session's name or id, a person's
    /// member id, or a project path for every live session there
    #[arg(long, value_name = "WHO")]
    pub(crate) to: Option<String>,

    /// Post to a named channel; `open` or `#open` posts to #open. With
    /// --to as well, the post stays in the channel, addressed to them
    #[arg(long, value_name = "NAME")]
    pub(crate) channel: Option<String>,

    /// Thread reply to a specific signal id (use `attend message reply` instead — it auto-threads)
    #[arg(long, value_name = "ID", hide = true)]
    pub(crate) re: Option<String>,

    /// Print the written signal as one JSON document
    #[arg(long)]
    pub(crate) json: bool,

    /// Message body (must follow all flags)
    #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
    pub(crate) message: Vec<String>,
}

#[derive(Args)]
pub(crate) struct ReplyArgs {
    /// Reply to this message id instead of the newest one delivered.
    /// The reply goes to its sender, or into its named channel, as
    /// without --re
    #[arg(long, value_name = "ID")]
    pub(crate) re: Option<String>,

    /// Send the reply as a direct message to this session, person or
    /// project path instead of to the parent's sender
    #[arg(long, value_name = "WHO")]
    pub(crate) to: Option<String>,

    /// Post the reply to this channel instead; `open` posts to #open
    #[arg(long, value_name = "NAME")]
    pub(crate) channel: Option<String>,

    /// Print the written signal as one JSON document
    #[arg(long)]
    pub(crate) json: bool,

    /// Message body (must follow all flags)
    #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
    pub(crate) message: Vec<String>,
}

#[derive(Args)]
pub(crate) struct InboxArgs {
    /// Specific message id to read in detail (omit to list inbox)
    pub(crate) msg_id: Option<String>,

    #[command(flatten)]
    pub(crate) flags: InboxFlags,
}

/// The inbox's flags, which also work on a bare `attend message`.
#[derive(Args)]
pub(crate) struct InboxFlags {
    /// Max messages per page, newest first
    #[arg(long, default_value_t = crate::verbs::inbox::DEFAULT_LIMIT)]
    pub(crate) limit: usize,

    /// Page number; 1 = newest. Higher numbers walk back into history.
    #[arg(long, default_value_t = 1)]
    pub(crate) page: usize,

    /// Cursor: only show messages older than this unix timestamp
    #[arg(long, value_name = "TS")]
    pub(crate) before: Option<u64>,

    /// Atomically deliver pending messages and record their
    /// consumption (ADR-172). The Stop-hook fast path: a silent no-op
    /// under an unresolved identity or for a session not enrolled by
    /// attend run or a channel join (#720). On a cold start (no
    /// seen-set) it delivers addressed mail and fresh messages and
    /// counts the older backlog it does not show.
    #[arg(long)]
    pub(crate) drain: bool,

    /// With --drain: deliver and mark nothing unless a pending message
    /// would wake this session, one addressed to it, sent to its
    /// project, a reply to a message it sent, or any post in one of its
    /// named channels; then deliver all that is pending. Other `#open`
    /// posts alone wait for the next turn (ADR-406 item 2). Once the session's prompt cache has
    /// lapsed (its tier's TTL less two minutes after its last turn, or
    /// no transcript readable in five seconds), nothing wakes it: the
    /// drain delivers nothing and reports `cache_lapsed`. The attend
    /// mod polls with it while idle.
    #[arg(long, requires = "drain")]
    pub(crate) wake: bool,

    /// Output format for --drain: `plain` (human/agent readable),
    /// `hook` (Claude Code Stop-hook JSON; reads the hook's stdin
    /// payload for `stop_hook_active`) or `json` (the same as --json)
    #[arg(long, default_value = "plain", value_name = "FMT")]
    pub(crate) format: String,

    /// Print the listing, the message, or with --drain the drained
    /// messages, held-back count, note and name, as one JSON document
    #[arg(long, conflicts_with = "format")]
    pub(crate) json: bool,
}

#[derive(Args)]
pub(crate) struct WhoamiArgs {
    /// Emit the stable key as `key=value` lines for scripts/hooks
    /// (session_id, origin_path, resolved) instead of the
    /// human-readable table. Downstream state must key on these
    /// fields — the display name is presentation, never a key.
    #[arg(long, conflicts_with = "display")]
    pub(crate) machine: bool,
    /// Print only the display name, for status lines and prompts.
    /// Presentation only: it can change between sessions, so never
    /// key state on it. An unresolved identity prints the name of
    /// the process cwd, with no notice.
    #[arg(long)]
    pub(crate) display: bool,
}

#[derive(Args)]
pub(crate) struct CleanupArgs {
    /// List what would be removed without deleting
    #[arg(long, short = 'n')]
    pub(crate) dry_run: bool,

    /// Remove every signal file regardless of project liveness
    #[arg(long)]
    pub(crate) all: bool,
}

#[derive(Args)]
#[command(group(clap::ArgGroup::new("scope").args(["open", "channel", "dm", "everywhere"])))]
pub(crate) struct DeleteArgs {
    /// Delete in #open
    #[arg(long)]
    pub(crate) open: bool,

    /// Delete in this channel
    #[arg(long, value_name = "NAME")]
    pub(crate) channel: Option<String>,

    /// Delete in the direct-message thread between you and this session:
    /// what it sent you and what you sent it. You are the session this runs
    /// in, under its current id and the ids it had before /clear, or
    /// outside a session the person at this terminal
    #[arg(long, value_name = "SESSION-ID")]
    pub(crate) dm: Option<String>,

    /// Delete in every room: #open, each channel, each project tray and
    /// each person's tray
    #[arg(long)]
    pub(crate) everywhere: bool,

    /// Only messages this session sent
    #[arg(long, value_name = "SESSION-ID")]
    pub(crate) from: Option<String>,

    /// Act as the person at this terminal, never as a Claude Code session
    /// this process runs under: `--dm` then reaches the person's thread.
    /// attend-chat passes it, since it may be started from a session's
    /// shell. A convenience for attend-chat, not an authorization check,
    /// so it is left out of the help; it takes `--dm`
    #[arg(long, hide = true)]
    pub(crate) as_person: bool,

    /// How old a message must be: `current` (before the earliest start of
    /// any live session), `today` (before local midnight), `all`, a
    /// duration such as 90m, 2h30m, 3d or 1w, or a local date YYYY-MM-DD
    #[arg(long, value_name = "WHEN", default_value = "all")]
    pub(crate) older_than: String,

    /// Report what would be marked and mark nothing
    #[arg(long, short = 'n')]
    pub(crate) dry_run: bool,

    /// Remove the marks of the newest delete, or of the batch named
    #[arg(long, value_name = "BATCH", num_args = 0..=1, default_missing_value = "", conflicts_with_all = ["scope", "from", "older_than", "dry_run", "as_person"])]
    pub(crate) undo: Option<String>,

    /// Print the result as one JSON document
    #[arg(long)]
    pub(crate) json: bool,
}

#[derive(Args)]
pub(crate) struct TombstoneArgs {
    /// The session to tombstone
    #[arg(value_name = "SESSION-ID", required_unless_present = "list")]
    pub(crate) session: Option<String>,

    /// Remove the session's tombstone. What a drain recorded read while it
    /// stood stays read
    #[arg(long, requires = "session")]
    pub(crate) undo: bool,

    /// List the tombstoned sessions
    #[arg(long, conflicts_with_all = ["session", "undo"])]
    pub(crate) list: bool,

    /// Print the result as one JSON document
    #[arg(long)]
    pub(crate) json: bool,
}

#[derive(Args)]
pub(crate) struct TuneArgs {
    /// Write the derived absolute_refractory, decay_per_minute and
    /// peer_activity_window to the user config, changing nothing else
    #[arg(long)]
    pub(crate) apply: bool,
}

/// Subcommands for `attend keepwarm`. With no subcommand, defaults to `status`.
#[derive(Subcommand)]
pub enum KeepwarmCmd {
    /// Arm a window: one wake at 50 idle minutes keeps the cache read, not re-written
    On {
        /// Window such as 6h, 90m, or 2h30m (default 6h)
        window: Option<String>,
    },
    /// Disarm and forget the window
    Off,
    /// Cache state, context size, cold price, window left, and this session's cold writes
    Status,
    /// Run the keepwarm judgment once: print the `keepwarm:` wake line when
    /// one is due, else nothing (exit 0 either way). For a host that polls
    /// without `attend run`; prints nothing while an `attend run` holds the
    /// session, since its sensor wakes it.
    Check,
}

/// Subcommands for `attend listen`. With no subcommand, defaults to `status`.
#[derive(Subcommand, Clone, Copy)]
pub enum ListenCmd {
    /// Listen: the Stop-hook drain delivers to this session. Messages
    /// addressed to its project while it was not listening are delivered by
    /// the next drain; older #open and channel backlog is held back
    On {
        /// What hosts delivery, when not Monitor or a shell: `mod`, the
        /// attend mod, whose agent answers with attend_reply and attend_send.
        /// The drain then delivers in the mod's format and names those tools
        #[arg(long, value_enum)]
        host: Option<ListenHost>,
    },
    /// Stop listening: the drain delivers nothing and marks nothing read.
    /// Channel memberships are kept; a later join, `attend run` or
    /// `listen on` listens again
    Off,
    /// Print `listening` or `not listening` (default)
    Status,
    /// Mark a listening session alive: touch its heartbeat, deliver
    /// nothing. After a /clear it first takes over the enrollment the
    /// session's earlier id made, as the drain does. The attend mod runs it
    /// on a timer, through turns too, so the session stays within the
    /// liveness grace while it lives. A session that does not listen is
    /// written nothing
    Beat,
}

/// A host `attend listen on --host` records.
#[derive(clap::ValueEnum, Clone, Copy, Debug)]
pub enum ListenHost {
    /// The attend mod (ADR-406)
    Mod,
}

/// Subcommands of the hidden `permissions` alias, which defaulted to `audit`.
#[derive(Subcommand)]
pub(crate) enum PermissionsCmd {
    /// Compare each sensor's `requires:` against settings.json
    Audit,
}

/// Subcommands for `attend config`. With no subcommand, defaults to `show`.
/// `ways settings` edits these settings; `ways settings help attend`
/// describes every key (ADR-503 §13).
#[derive(Subcommand)]
pub(crate) enum ConfigCmd {
    /// Write the default config file to the user scope, if none is there
    Init,

    /// Print each setting in effect as key=value (default)
    Show,

    /// Print the user/project config file paths
    Path,

    /// Check the config files against the schema; exit 3 with findings
    Lint,

    /// Survey session history and derive engagement config
    Tune(TuneArgs),
}

#[cfg(test)]
mod tests {
    use super::*;
    use clap::CommandFactory;

    /// The subcommand at a space-separated path such as `message send`.
    fn at(cli: &clap::Command, path: &str) -> clap::Command {
        path.split(' ').fold(cli.clone(), |cmd, name| {
            cmd.find_subcommand(name).unwrap_or_else(|| panic!("no `{path}` subcommand")).clone()
        })
    }

    /// Each message verb's help says exactly its `describe` string, the one
    /// description every frontend reads (ADR-501 item 4).
    #[test]
    fn message_verb_help_is_the_shared_description() {
        let cli = Cli::command();
        for (path, text) in describe::VERBS {
            let sub = at(&cli, path);
            assert_eq!(sub.get_about().map(|s| s.to_string()).as_deref(), Some(*text), "{path}");
            assert!(sub.get_long_about().is_none(), "{path} has no second description");
        }
    }

    /// Every message verb takes `--json`.
    #[test]
    fn message_verbs_take_json() {
        let cli = Cli::command();
        for (path, _) in describe::VERBS {
            let sub = at(&cli, path);
            assert!(sub.get_arguments().any(|a| a.get_long() == Some("json")), "{path} lacks --json");
        }
    }

    /// `attend --help` lists the nine groups and none of the aliases
    /// (ADR-413 items 1 and 5).
    #[test]
    fn help_lists_the_nine_commands() {
        let cli = Cli::command();
        let shown: Vec<&str> = cli.get_subcommands().filter(|c| !c.is_hide_set()).map(|c| c.get_name()).collect();
        assert_eq!(shown, ["run", "listen", "message", "channel", "peer", "keepwarm", "chat", "sensor", "config"]);
    }

    /// The help states the limits the code applies.
    #[test]
    fn help_states_the_limits_in_force() {
        let cli = crate::cli_command();
        let delete = at(&cli, "message delete").get_long_about().unwrap().to_string();
        let grace = attend_presence::heartbeat::DEFAULT_GRACE.as_secs();
        for text in [
            format!("older than {grace} seconds"),
            format!("{} days after the mark", crate::cmd::cleanup::MARK_REAP_DAYS),
            format!("started {} Claude Code sessions", crate::cmd::cleanup::MARK_REAP_SESSIONS),
        ] {
            assert!(delete.contains(&text), "{text} in {delete}");
        }
        let cleanup = at(&cli, "message cleanup").get_about().unwrap().to_string();
        assert!(cleanup.contains(&format!("{} days", crate::cmd::cleanup::MARK_REAP_DAYS)), "{cleanup}");
        let tombstone = at(&cli, "message tombstone").get_long_about().unwrap().to_string();
        assert!(tombstone.contains("attend message delete --everywhere --from <id>"), "{tombstone}");
    }

    /// Writing the limits into the help keeps every verb where it is declared.
    #[test]
    fn the_limits_keep_the_declared_order() {
        let names = |c: &clap::Command| c.get_subcommands().map(|s| s.get_name().to_string()).collect::<Vec<_>>();
        let (declared, written) = (Cli::command(), crate::cli_command());
        assert_eq!(names(&written), names(&declared));
        assert_eq!(names(&at(&written, "message")), ["send", "reply", "inbox", "unread", "cleanup", "delete", "tombstone"]);
    }

    #[test]
    fn clap_tree_is_valid() {
        Cli::command().debug_assert();
    }
}
